namespace porytiles {

/// @brief Search algorithm used by BacktrackingStrategy.
///
/// @details
/// Controls whether the backtracking search explores the solution space using depth-first or breadth-first traversal.
/// DFS uses in-place mutation with undo for memory efficiency, while BFS uses visited-state deduplication and a
/// dual-queue heuristic.
///
enum class SearchAlgorithm {
    /// @brief Depth-first search with in-place mutation and undo.
    dfs,
    /// @brief Breadth-first search with dual-queue heuristic and visited-state deduplication.
    bfs
};

/// @brief Parses a string into a SearchAlgorithm with fuzzy matching.
///
/// @details
/// Performs parsing in two phases:
/// 1. Exact match against C++ constant names (snake_case)
/// 2. Case-insensitive fuzzy match against configured fuzzy_names
///
/// This unified function is used by both CLI and YAML parsing. The fuzzy matching
/// allows users to use various common formats (kebab-case, snake_case, etc.) while
/// still getting good error messages through LazyLayeredConfig.
///
/// @param str The string to parse
/// @return The parsed value, or std::nullopt if the string is invalid
[[nodiscard]] inline std::optional<SearchAlgorithm> search_algorithm_from_str(const std::string &str)
{
    // Phase 1: Exact match against C++ constant names
    if (str == "dfs") {
        return std::optional{SearchAlgorithm::dfs};
    }
    if (str == "bfs") {
        return std::optional{SearchAlgorithm::bfs};
    }

    // Phase 2: Case-insensitive fuzzy match
    std::string lower_str = str;
    std::ranges::transform(
        lower_str, lower_str.begin(), [](unsigned char c) { return static_cast<char>(std::tolower(c)); });

    // Fuzzy names for dfs
    if (lower_str == "dfs") {
        return std::optional{SearchAlgorithm::dfs};
    }
    if (lower_str == "depth-first") {
        return std::optional{SearchAlgorithm::dfs};
    }
    if (lower_str == "depth_first") {
        return std::optional{SearchAlgorithm::dfs};
    }
    if (lower_str == "depthfirst") {
        return std::optional{SearchAlgorithm::dfs};
    }
    // Fuzzy names for bfs
    if (lower_str == "bfs") {
        return std::optional{SearchAlgorithm::bfs};
    }
    if (lower_str == "breadth-first") {
        return std::optional{SearchAlgorithm::bfs};
    }
    if (lower_str == "breadth_first") {
        return std::optional{SearchAlgorithm::bfs};
    }
    if (lower_str == "breadthfirst") {
        return std::optional{SearchAlgorithm::bfs};
    }

    return std::nullopt;
}

/// @brief Converts a SearchAlgorithm to its canonical string representation.
///
/// @details
/// Returns the C++ constant name (snake_case). This is the canonical form used for
/// general purpose string conversion, logging, and error messages.
///
/// @param m The value to convert
/// @return The canonical snake_case string representation
[[nodiscard]] inline std::string to_string(const SearchAlgorithm m)
{
    switch (m) {
    case SearchAlgorithm::dfs:
        return "dfs";
    case SearchAlgorithm::bfs:
        return "bfs";
    }
    panic("unhandled SearchAlgorithm value");
}

/// @brief Stream insertion operator for SearchAlgorithm.
///
/// @param os The output stream
/// @param m The value to output
/// @return Reference to the output stream
inline std::ostream &operator<<(std::ostream &os, const SearchAlgorithm m)
{
    return os << to_string(m);
}

} // namespace porytiles

template <>
struct std::formatter<porytiles::SearchAlgorithm> {
    constexpr auto parse(std::format_parse_context &ctx)
    {
        return ctx.begin();
    }

    auto format(const porytiles::SearchAlgorithm &value, auto &ctx) const
    {
        return std::format_to(ctx.out(), "{}", porytiles::to_string(value));
    }
};